steps.script:
var mgr = SecondaryMissionManager
var p = GameState.get_active_player()
var opp = 2 if p == 1 else 1
Engine.set_meta("soh_player", p)
GameState.state["meta"]["game_config"]["player%d_type" % p] = "HUMAN"
GameState.state["meta"]["game_config"]["player%d_type" % opp] = "HUMAN"
for k in [p, opp]:
	if not mgr.is_initialized(k):
		mgr.setup_tactical_deck(k)
	mgr._player_state[str(k)]["mode"] = "tactical"
	mgr._player_state[str(k)]["active"] = []
var st = mgr._player_state[str(p)]
for mid in ["display_of_might", "assassination"]:
	st["active"].append(mgr._create_active_mission(SecondaryMissionData.get_mission_by_id(mid)))
var z1 = mgr._get_deployment_zone_polygon(1)
var z2 = mgr._get_deployment_zone_polygon(2)
var opp_zone = z2 if opp == 2 else z1
var opp_c = Vector2.ZERO
for v in opp_zone:
	opp_c += v
opp_c /= max(1, opp_zone.size())
# Own units: points between the zones (No Man's Land), found by scanning the
# board for 3 spaced points outside BOTH deployment zones.
var bw = Measurement.inches_to_px(float(GameState.state.get("board", {}).get("size", {}).get("width", 44)))
var bh = Measurement.inches_to_px(float(GameState.state.get("board", {}).get("size", {}).get("height", 60)))
var spots = []
var step = Measurement.inches_to_px(6.0)
var y = bh * 0.5
var x = bw * 0.2
while x < bw * 0.85 and spots.size() < 3:
	var ok = true
	for dx in [0.0, Measurement.inches_to_px(3.0)]:
		for dy in [0.0, Measurement.inches_to_px(3.0)]:
			var q = Vector2(x + dx, y + dy)
			if Geometry2D.is_point_in_polygon(q, z1) or Geometry2D.is_point_in_polygon(q, z2):
				ok = false
	if ok:
		spots.append(Vector2(x, y))
	x += step
var placed = 0
var enemy_i = 0
for uid in GameState.state["units"].keys():
	var u = GameState.state["units"][uid]
	var models = u.get("models", [])
	if models.size() == 0:
		continue
	if int(u.get("owner", 0)) == p:
		if placed >= spots.size():
			continue
		var c = spots[placed]
		var mi = 0
		for m in models:
			m["position"] = {"x": c.x + Measurement.inches_to_px((mi % 3) * 1.3), "y": c.y + Measurement.inches_to_px(int(mi / 3) * 1.3)}
			m["alive"] = true
			mi += 1
		placed += 1
	else:
		# Enemy units: inside their own deployment zone (never NML)
		for m in models:
			m["position"] = {"x": opp_c.x + Measurement.inches_to_px((enemy_i % 5) * 0.5), "y": opp_c.y}
		enemy_i += 1
var nml_own = mgr._count_units_wholly_in_nml(p, [])
var nml_opp = mgr._count_units_wholly_in_nml(opp, [])
return "own_more_in_nml=%s opp_nml=%d" % [str(nml_own > nml_opp), nml_opp]

var p = GameState.get_active_player()
var pend = SecondaryMissionManager.get_pending_secondary_scores(p)
return str(pend)

var sc = tree.root.get_node_or_null("Main/HUD_Right/VBoxContainer/ScoringScrollContainer")
var hold = sc.find_child("HoldSecondaryButton", true, false)
var score = sc.find_child("ScoreSecondaryButton", true, false)
sc.ensure_control_visible(score)
return "%s|%s|%s" % [score.text, str(score.button_pressed), str(hold.button_pressed)]

var sc = tree.root.get_node_or_null("Main/HUD_Right/VBoxContainer/ScoringScrollContainer")
sc.find_child("HoldSecondaryButton", true, false).pressed.emit()
return true

var sc = tree.root.get_node_or_null("Main/HUD_Right/VBoxContainer/ScoringScrollContainer")
var lbl = sc.find_child("ScoreChoiceLabel", true, false)
var hold = sc.find_child("HoldSecondaryButton", true, false)
sc.ensure_control_visible(hold)
return "%s|%s" % [lbl.text.begins_with("HOLDING"), str(hold.button_pressed)]

var d = tree.root.get_node_or_null('MissionDiscardDialog')
if d == null:
	return "no dialog"
var pair = d._score_hold_buttons.get("display_of_might", [])
return "%s|%s|%s|%s" % [d.title, pair[0].text, str(pair[0].button_pressed), str(pair[1].button_pressed)]
